-- 3. Sample Mixed Course Sources (Video, PDF, TXT/MD, XLSX, YouTube, Web URL)
INSERT OR IGNORE INTO course_sources (id, course_id, source_type, title, origin_url, search_query, file_hash, storage_key, raw_text_excerpt, structured_chunks_json, visual_assets_json, discovered_links_json, metadata_json, status) VALUES ('src-sample-video', 'course-sample-cs-core', 'video', '4_Subject_Split_Lecture.mp4', '', '', 'a1b2c3d4e5f60001a1b2c3d4e5f60001a1b2c3d4e5f60001a1b2c3d4e5f60001', 'courses/course-sample-cs-core/4_Subject_Split_Lecture.mp4', 'Multi-window 2x2 lecture covering Data Structures AVL rotations and Dijkstra shortest paths, POSIX Shell Scripting pipelines with grep awk sed, DBMS BCNF normalization and ARIES write-ahead logging, and Machine Learning gradient descent with bias-variance tradeoff.', '[{"label": "00:00-15:00", "text": "AVL tree height balance factor and Quicksort partitioning"}, {"label": "15:00-30:00", "text": "Shell exit codes, redirection 2>&1, and awk field sums"}, {"label": "30:00-45:00", "text": "DBMS 3NF vs BCNF lossless decomposition and ARIES phases"}, {"label": "45:00-60:00", "text": "Gradient descent convergence, L2 ridge penalty, and SVM margins"}]', '[]', '[]', '{"duration_sec": 3600, "layout": "2x2", "resolution": "1920x1080"}', 'PARSED');
INSERT OR IGNORE INTO course_sources (id, course_id, source_type, title, origin_url, search_query, file_hash, storage_key, raw_text_excerpt, structured_chunks_json, visual_assets_json, discovered_links_json, metadata_json, status) VALUES ('src-sample-pdf', 'course-sample-cs-core', 'pdf', 'MIT_6006_Trees_and_Heaps.pdf', 'https://ocw.mit.edu/courses/6-006/trees-heaps.pdf', 'AVL trees heaps asymptotic complexity', 'a1b2c3d4e5f60002a1b2c3d4e5f60002a1b2c3d4e5f60002a1b2c3d4e5f60002', 'courses/course-sample-cs-core/MIT_6006_Trees_and_Heaps.pdf', 'Binary search trees maintain the invariant that left keys <= root <= right keys. AVL trees enforce balance factor bf in {-1, 0, +1} via single LL/RR and double LR/RL rotations yielding worst-case O(log n) search, insert, and delete. Binary max-heaps support build-heap in O(n).', '[{"page": 1, "text": "BST invariants and in-order traversal sorted output"}, {"page": 4, "text": "AVL rotations (LL, RR, LR, RL) and height bound 1.44 log2(n)"}, {"page": 9, "text": "Priority queues, Floyd linear-time heapify O(n), and Heapsort"}]', '[]', '[]', '{"page_count": 14, "author": "MIT OpenCourseWare"}', 'PARSED');
INSERT OR IGNORE INTO course_sources (id, course_id, source_type, title, origin_url, search_query, file_hash, storage_key, raw_text_excerpt, structured_chunks_json, visual_assets_json, discovered_links_json, metadata_json, status) VALUES ('src-sample-txt', 'course-sample-cs-core', 'txt', 'POSIX_Shell_Cheatsheet.md', '', '', 'a1b2c3d4e5f60003a1b2c3d4e5f60003a1b2c3d4e5f60003a1b2c3d4e5f60003', 'courses/course-sample-cs-core/POSIX_Shell_Cheatsheet.md', 'Always guard production bash scripts with set -euo pipefail and IFS=$''\n\t''. Use grep -E for extended regex filtering, sed -E for stream substitution, and awk -F'','' for columnar aggregation. Quote variable expansions "$var" to prevent word splitting and globbing.', '[{"section": "Safety Header", "text": "set -euo pipefail, trap cleanup EXIT, quoting rules"}, {"section": "Text Pipelines", "text": "grep, sed, awk, sort -u, uniq -c, xargs -0"}]', '[]', '[]', '{"encoding": "utf-8", "lines": 142}', 'PARSED');
INSERT OR IGNORE INTO course_sources (id, course_id, source_type, title, origin_url, search_query, file_hash, storage_key, raw_text_excerpt, structured_chunks_json, visual_assets_json, discovered_links_json, metadata_json, status) VALUES ('src-sample-xlsx', 'course-sample-cs-core', 'xlsx', 'DBMS_Normalization_Lab_Matrix.xlsx', '', '', 'a1b2c3d4e5f60004a1b2c3d4e5f60004a1b2c3d4e5f60004a1b2c3d4e5f60004', 'courses/course-sample-cs-core/DBMS_Normalization_Lab_Matrix.xlsx', 'Sheet NormalForms compares 1NF, 2NF, 3NF, BCNF, and 4NF anomalies. BCNF guarantees every non-trivial functional dependency X -> Y has X as a superkey, eliminating redundancy while preserving lossless-join decomposition.', '[{"sheet": "NormalForms", "text": "| Form | Eliminates | Preserves Dependencies |"}, {"sheet": "ARIES_Log_Trace", "text": "| LSN | TransID | Type | PrevLSN | PageID |"}]', '[]', '[]', '{"sheet_names": ["NormalForms", "ARIES_Log_Trace"], "rows": 48}', 'PARSED');
INSERT OR IGNORE INTO course_sources (id, course_id, source_type, title, origin_url, search_query, file_hash, storage_key, raw_text_excerpt, structured_chunks_json, visual_assets_json, discovered_links_json, metadata_json, status) VALUES ('src-sample-youtube', 'course-sample-cs-core', 'youtube', 'CMU Database Group: ARIES Crash Recovery & WAL', 'https://www.youtube.com/watch?v=aries-recovery-demo', 'ARIES database crash recovery', 'a1b2c3d4e5f60005a1b2c3d4e5f60005a1b2c3d4e5f60005a1b2c3d4e5f60005', '', 'ARIES Write-Ahead Logging uses steal/no-force buffer management. Upon crash restart: (1) Analysis scans forward from last checkpoint to rebuild Dirty Page Table and Active Transaction Table; (2) Redo repeats history from min RecLSN; (3) Undo rolls back loser transactions writing CLR records.', '[{"timestamp": "04:12", "text": "Steal / No-Force policy and LSN / PageLSN invariants"}, {"timestamp": "18:40", "text": "Analysis, Redo repeating history, and Undo with CLRs"}]', '[]', '[]', '{"channel": "CMU Database Group", "duration_sec": 3240}', 'PARSED');
INSERT OR IGNORE INTO course_sources (id, course_id, source_type, title, origin_url, search_query, file_hash, storage_key, raw_text_excerpt, structured_chunks_json, visual_assets_json, discovered_links_json, metadata_json, status) VALUES ('src-sample-web', 'course-sample-cs-core', 'web_url', 'Stanford CS229 Bias-Variance & SVM Notes', 'https://cs229.stanford.edu/notes/bias-variance-svm', 'bias variance tradeoff support vector machine', 'a1b2c3d4e5f60006a1b2c3d4e5f60006a1b2c3d4e5f60006a1b2c3d4e5f60006', '', 'Expected generalization error decomposes into Bias^2 + Variance + irreducible noise. Support Vector Machines maximize geometric margin 2 / ||w|| subject to y_i(w^T x_i + b) >= 1 - xi_i using RBF or polynomial kernels for non-linear decision boundaries.', '[{"section": "Bias-Variance", "text": "Underfitting high bias vs overfitting high variance"}, {"section": "SVM Margin", "text": "Dual Lagrangian, KKT complementary slackness, RBF kernel"}]', '[]', '["https://cs229.stanford.edu/main_notes.pdf"]', '{"domain": "cs229.stanford.edu", "linked_pdfs": 1}', 'PARSED');

-- 4. Four Sample Subjects (Data Structures, Shell Scripting, DBMS, Machine Learning)
INSERT OR IGNORE INTO subjects (id, course_id, quadrant_key, title, short_title, topic, unit, instructor, badge_color, summary, subtitles_transcript, slide_crops, source_citations, mermaid_diagram) VALUES ('subj-ds', 'course-sample-cs-core', 'top_left', 'Data Structures', 'DSA', 'Sorting, Balanced Trees & Graph Algorithms', 'Unit II & III', 'Prof. A. Kulkarni', '#3B82F6', 'Covers asymptotic complexity analysis via Master Theorem, AVL self-balancing tree rotations, linear-time heap construction, open-addressing hash tables, and BFS/DFS/Dijkstra graph traversal.', '[{"timestamp": "00:02:10", "text": "Master Theorem resolves recurrences T(n) = aT(n/b) + f(n) across three cases."}, {"timestamp": "00:08:15", "text": "An AVL tree checks balance factor bf = height(left) - height(right) in {-1, 0, +1}."}, {"timestamp": "00:12:40", "text": "Dijkstra uses a min-priority queue for O((V + E) log V) with non-negative weights."}]', '[{"url": "data:image/svg+xml;base64,", "caption": "AVL Left-Right Double Rotation", "citation": "From: MIT_6006_Trees_and_Heaps.pdf p.4", "source_id": "src-sample-pdf", "timestamp": "00:08:15"}, {"url": "data:image/svg+xml;base64,", "caption": "Sorting & Graph Complexity Comparison", "citation": "From: 4_Subject_Split_Lecture.mp4 12:40", "source_id": "src-sample-video", "timestamp": "00:12:40"}]', '[{"source_id": "src-sample-pdf", "title": "MIT_6006_Trees_and_Heaps.pdf", "location": "pp. 1-9"}, {"source_id": "src-sample-video", "title": "4_Subject_Split_Lecture.mp4", "location": "00:00-15:00"}]', 'flowchart TD
    A["Unsorted Array O(n^2) Bubble/Selection"] --> B["Divide and Conquer O(n log n) Merge/Quick"]
    B --> C["Balanced BST / AVL Rotations O(log n)"]
    C --> D["Dijkstra & BFS/DFS Graph Traversal O(V + E)"]');
INSERT OR IGNORE INTO subject_details (subject_id, key_concepts, math_formulas) VALUES ('subj-ds', '[{"title": "AVL Tree Rotations & Height Bound", "explanation": "Every node maintains |height(L) - height(R)| <= 1. Violations trigger LL, RR, LR, or RL rotations in O(1) pointer updates, keeping height <= 1.44 log2(n).", "citation": "MIT_6006_Trees_and_Heaps.pdf p.4"}, {"title": "Master Theorem Recurrences", "explanation": "Compares f(n) against watershed n^(log_b a). Case 1: leaves dominate; Case 2: balanced work per level (multiply by log n); Case 3: root dominates.", "citation": "4_Subject_Split_Lecture.mp4 02:10"}, {"title": "Floyd Linear-Time Build-Heap", "explanation": "Running sift-down bottom-up from index n/2 down to 1 builds a valid binary heap in O(n) rather than O(n log n) because most nodes lie near the leaves.", "citation": "MIT_6006_Trees_and_Heaps.pdf p.9"}, {"title": "Dijkstra vs Bellman-Ford Shortest Paths", "explanation": "Dijkstra greedily relaxes edges for non-negative weights in O((V+E) log V); negative edge weights require Bellman-Ford in O(VE).", "citation": "4_Subject_Split_Lecture.mp4 12:40"}]', '[{"name": "Master Theorem Case 2 (Merge Sort)", "latex": "T(n) = 2T(n/2) + \\Theta(n) \\implies \\Theta(n \\log n)", "note": "Equal work at every recursion depth"}, {"name": "Minimum Nodes in AVL Tree of Height h", "latex": "N(h) = N(h-1) + N(h-2) + 1 \\approx \\phi^{h+2} - 1", "note": "Fibonacci-like recurrence guarantees logarithmic height"}, {"name": "Dijkstra Binary Heap Complexity", "latex": "\\mathcal{O}\\big((|V| + |E|)\\log |V|\\big)", "note": "Valid strictly when all edge weights w(u,v) >= 0"}]');
