INSERT OR IGNORE INTO quizzes (subject_id, questions_json) VALUES ('subj-ds', '[{"id": "ds-q1", "question": "What is the tight worst-case time complexity of building a binary heap from an unsorted array of n elements using bottom-up heapify?", "options": ["O(n)", "O(n log n)", "O(log n)", "O(n^2)"], "correct_index": 0, "explanation": "Most nodes are near the bottom of the tree and travel at most 1-2 levels; the geometric series sums to <= 2n = O(n).", "citation": "MIT_6006_Trees_and_Heaps.pdf p.9"}, {"id": "ds-q2", "question": "Inserting a node into an AVL tree causes a Left-Right (LR) imbalance at node z. Which rotation sequence restores balance?", "options": ["Left-rotate left child of z, then Right-rotate z", "Right-rotate z, then Left-rotate right child of z", "Single Right-rotate at z", "Single Left-rotate at z"], "correct_index": 0, "explanation": "An LR imbalance is a zig-zag; first straighten it with a left rotation on the left child, then right-rotate z.", "citation": "MIT_6006_Trees_and_Heaps.pdf p.4"}, {"id": "ds-q3", "question": "Which recurrence solves to Theta(n log n) by Case 2 of the Master Theorem?", "options": ["T(n) = 2T(n/2) + n", "T(n) = 4T(n/2) + n", "T(n) = 2T(n/2) + n^2", "T(n) = T(n-1) + 1"], "correct_index": 0, "explanation": "Here a=2, b=2 so n^(log_2 2) = n^1, matching f(n) = n, giving Theta(n log n).", "citation": "4_Subject_Split_Lecture.mp4 02:10"}, {"id": "ds-q4", "question": "Why does Dijkstra''s algorithm fail on graphs containing negative-weight edges?", "options": ["A finalized vertex distance may still be reduced later via a negative edge", "Adjacency lists cannot store negative integers", "BFS queue overflows on negative cycles", "It converts undirected edges to directed edges"], "correct_index": 0, "explanation": "Dijkstra''s greedy choice assumes path costs only increase as edges are added.", "citation": "4_Subject_Split_Lecture.mp4 12:40"}, {"id": "ds-q5", "question": "Which sorting algorithm guarantees O(n log n) worst-case time AND stability?", "options": ["Merge Sort", "Quicksort (Lomuto)", "Heapsort", "Selection Sort"], "correct_index": 0, "explanation": "Merge Sort preserves relative order of equal keys and runs in O(n log n) in all cases.", "citation": "4_Subject_Split_Lecture.mp4 12:40"}]');
INSERT OR IGNORE INTO model_papers (subject_id, title, time_allowed, max_marks, questions_json) VALUES ('subj-ds', 'University Model Exam Paper — Data Structures', '60 Minutes', 25, '[{"id": "ds-mp-1", "section": "Section A", "marks": 2, "question": "Define the AVL balance factor invariant and state the maximum height of an AVL tree with n nodes.", "rubric": ["Balance factor bf in {-1, 0, +1} (1m)", "Height <= 1.44 log2(n+2) - 0.328 (1m)"], "model_answer": "Each node satisfies bf = h(left) - h(right) in {-1, 0, +1}, guaranteeing height O(log n) bounded by ~1.44 log2(n)."}, {"id": "ds-mp-2", "section": "Section A", "marks": 3, "question": "Solve T(n) = 4T(n/2) + n using the Master Theorem.", "rubric": ["Compute n^(log_2 4) = n^2 (1m)", "Compare f(n)=n vs n^2 Case 1 (1m)", "Conclude Theta(n^2) (1m)"], "model_answer": "a=4, b=2 -> watershed n^2. Since f(n)=n = O(n^(2-1)), Case 1 applies: T(n) = Theta(n^2)."}, {"id": "ds-mp-3", "section": "Section B", "marks": 5, "question": "Insert keys [30, 10, 20, 40, 50] sequentially into an initially empty AVL tree and name every rotation triggered.", "rubric": ["Show LR imbalance at 30 on inserting 20 (2m)", "Correctly show tree after LR rotation: root 20 (1m)", "Show RR imbalance & Left-Rotation at 30 on inserting 50 (2m)"], "model_answer": "Inserting 30, 10, 20 creates LR imbalance at 30 -> LR double rotation makes 20 root (10 left, 30 right). Adding 40, 50 creates RR imbalance at 30 -> Left-rotate(30) gives subtree root 40 (30 left, 50 right)."}, {"id": "ds-mp-4", "section": "Section B", "marks": 5, "question": "Explain why bottom-up Build-Heap runs in O(n) time instead of O(n log n).", "rubric": ["State sift-down start at floor(n/2) (1m)", "Sum nodes at height h times max swaps h (2m)", "Evaluate convergent series sum h/2^h = 2 -> O(n) (2m)"], "model_answer": "At height h there are <= ceil(n / 2^(h+1)) nodes each doing <= h swaps. Total work <= sum_{h=0}^{log n} n * h / 2^(h+1) <= n * 1 = O(n)."}, {"id": "ds-mp-5", "section": "Section C", "marks": 10, "question": "Design a shortest-path router for a campus network with non-negative latencies: compare Adjacency Matrix vs Adjacency List Dijkstra, derive time complexity, and state how negative latency anomalies must be handled.", "rubric": ["Data structure choice & heap decrease-key / lazy deletion (3m)", "O((V+E) log V) vs O(V^2) sparse/dense trade-off (4m)", "Negative-weight failure explanation + Bellman-Ford fallback O(VE) (3m)"], "model_answer": "Use adjacency list + binary min-heap for sparse graphs yielding O((V+E) log V), vs O(V^2) array scan on dense graphs. Because greedy finalization breaks with negative edges, detect negative cycles and fall back to Bellman-Ford in O(VE)."}]');
INSERT OR IGNORE INTO subjects (id, course_id, quadrant_key, title, short_title, topic, unit, instructor, badge_color, summary, subtitles_transcript, slide_crops, source_citations, mermaid_diagram) VALUES ('subj-shell', 'course-sample-cs-core', 'top_right', 'Shell Scripting', 'Shell', 'POSIX Bash Pipelines, Awk/Sed & Process Control', 'Unit I & II', 'Prof. R. Menon', '#10B981', 'Covers POSIX shell strict mode, file descriptor redirection (stdin/stdout/stderr), text stream filtering with grep/sed/awk, exit status logic, signals/traps, and safe quoting.', '[{"timestamp": "00:16:05", "text": "Use 2>&1 after > logfile so stderr merges into the redirected stdout descriptor."}, {"timestamp": "00:21:30", "text": "In awk, NR tracks record count and NF gives fields in the current line."}, {"timestamp": "00:26:50", "text": "set -euo pipefail aborts immediately on unset variables or failing pipeline stages."}]', '[{"url": "data:image/svg+xml;base64,", "caption": "File Descriptor Redirection Order", "citation": "From: POSIX_Shell_Cheatsheet.md", "source_id": "src-sample-txt", "timestamp": "00:16:05"}, {"url": "data:image/svg+xml;base64,", "caption": "AWK BEGIN / Pattern-Action / END", "citation": "From: 4_Subject_Split_Lecture.mp4 21:30", "source_id": "src-sample-video", "timestamp": "00:21:30"}]', '[{"source_id": "src-sample-txt", "title": "POSIX_Shell_Cheatsheet.md", "location": "Lines 1-142"}, {"source_id": "src-sample-video", "title": "4_Subject_Split_Lecture.mp4", "location": "15:00-30:00"}]', 'flowchart LR
    A["Stdin Stream"] --> B["grep -E Pattern Filter"]
    B --> C["awk Field Transform"]
    C --> D["sed Stream Edit"]
    D --> E["Exit Code 0 / Pipe Output"]');
INSERT OR IGNORE INTO subject_details (subject_id, key_concepts, math_formulas) VALUES ('subj-shell', '[{"title": "Left-to-Right Redirection Evaluation", "explanation": "Shell evaluates redirections left-to-right: `cmd > file 2>&1` points FD 1 to `file` then duplicates FD 1 onto FD 2; reversing to `2>&1 > file` leaves stderr on the terminal.", "citation": "4_Subject_Split_Lecture.mp4 16:05"}, {"title": "Bash Strict Mode (set -euo pipefail)", "explanation": "`-e` exits on non-zero status, `-u` errors on undefined variables, and `-o pipefail` returns the rightmost non-zero pipeline exit status instead of hiding errors.", "citation": "POSIX_Shell_Cheatsheet.md"}, {"title": "AWK Pattern-Action & Built-in Variables", "explanation": "Processes text line-by-line splitting on `FS`. `NR` is row number, `NF` is field count, `$0` is the whole line, and `END` executes aggregate summaries.", "citation": "4_Subject_Split_Lecture.mp4 21:30"}, {"title": "Safe Quoting & Word Splitting", "explanation": "Double-quoting `\"$filename\"` prevents IFS word splitting and pathname glob expansion on filenames containing spaces or asterisks.", "citation": "POSIX_Shell_Cheatsheet.md"}]', '[{"name": "POSIX chmod Octal Permission Mask", "latex": "M = 4\\cdot r + 2\\cdot w + 1\\cdot x \\quad (0 \\le M \\le 7)", "note": "Applied independently per User, Group, Others triad (e.g. 0750)"}, {"name": "Signal Termination Exit Code", "latex": "\\text{exit\\_code} = 128 + \\text{signal\\_num}", "note": "SIGINT (2) -> 130; SIGKILL (9) -> 137; SIGTERM (15) -> 143"}, {"name": "Pipeline Throughput Bound", "latex": "T_{\\text{pipe}} = \\max_{k} T_k + \\mathcal{O}(\\text{context switches})", "note": "Bounded by the slowest concurrent stage"}]');
