INSERT OR IGNORE INTO quizzes (subject_id, questions_json) VALUES ('subj-shell', '[{"id": "shell-q1", "question": "Which redirection sends BOTH stdout and stderr of `build.sh` into `build.log`?", "options": ["./build.sh > build.log 2>&1", "./build.sh 2>&1 > build.log", "./build.sh > 2>&1 build.log", "./build.sh | build.log"], "correct_index": 0, "explanation": "Redirections evaluate left-to-right; FD 1 must be bound to build.log before FD 2 copies FD 1.", "citation": "4_Subject_Split_Lecture.mp4 16:05"}, {"id": "shell-q2", "question": "In `awk -F'':'' ''{print $1, NF}'' /etc/passwd`, what does `NF` output?", "options": ["Number of colon-delimited fields on the current line", "Total number of lines read so far", "Current filename string", "Byte offset of the line"], "correct_index": 0, "explanation": "NF is Number of Fields in the current record; NR is Number of Records.", "citation": "4_Subject_Split_Lecture.mp4 21:30"}, {"id": "shell-q3", "question": "What does `set -o pipefail` change in `false | true`?", "options": ["The pipeline returns 1 instead of 0", "The pipeline spawns an extra background subshell", "Stdout is buffered until EOF", "It ignores SIGPIPE"], "correct_index": 0, "explanation": "Without pipefail, a pipeline exits with the status of its last command (`true` = 0).", "citation": "POSIX_Shell_Cheatsheet.md"}, {"id": "shell-q4", "question": "Which numeric `chmod` mode grants rwx to owner, r-x to group, and --- to others?", "options": ["0750", "0755", "0640", "0741"], "correct_index": 0, "explanation": "Owner 4+2+1=7, Group 4+0+1=5, Others 0+0+0=0 -> 0750.", "citation": "POSIX_Shell_Cheatsheet.md"}, {"id": "shell-q5", "question": "Why should `find . -name ''*.log'' -print0 | xargs -0 rm` be preferred over `$(find . -name ''*.log'')`?", "options": ["NUL delimiters safely handle filenames with spaces, quotes, and newlines", "xargs -0 compresses files before deletion", "Subshells cannot execute `rm`", "find refuses to run inside command substitution"], "correct_index": 0, "explanation": "NUL (\\0) is the only byte disallowed in POSIX filenames, preventing word-splitting bugs.", "citation": "POSIX_Shell_Cheatsheet.md"}]');
INSERT OR IGNORE INTO model_papers (subject_id, title, time_allowed, max_marks, questions_json) VALUES ('subj-shell', 'University Model Exam Paper — Shell Scripting', '60 Minutes', 25, '[{"id": "shell-mp-1", "section": "Section A", "marks": 2, "question": "Explain the difference between single quotes `''...''` and double quotes `\"...\"` in POSIX shells.", "rubric": ["Single quotes suppress all expansions (1m)", "Double quotes preserve literal spacing while allowing $var and $(cmd) (1m)"], "model_answer": "Single quotes preserve every character literally; double quotes prevent word splitting and globbing while allowing parameter and command substitutions."}, {"id": "shell-mp-2", "section": "Section A", "marks": 3, "question": "Why does `./app 2>&1 > out.txt` fail to redirect stderr to `out.txt`?", "rubric": ["Left-to-right evaluation rule (1m)", "FD 2 points to old FD 1 (tty) first (1m)", "Fix: `> out.txt 2>&1` (1m)"], "model_answer": "FD 2 is duplicated to FD 1 (still the terminal) before FD 1 is redirected to out.txt. Reversing to `> out.txt 2>&1` fixes it."}, {"id": "shell-mp-3", "section": "Section B", "marks": 5, "question": "Write an `awk` one-liner over a CSV (`user,dept,status,score`) that prints each department''s average score for rows where `status == \"PASS\"`.", "rubric": ["Set FS='','' (1m)", "Filter $3 == \"PASS\" and accumulate sums/counts per $2 (2m)", "END block iterates array and prints sum/count (2m)"], "model_answer": "awk -F'','' ''$3==\"PASS\" {sum[$2]+=$4; cnt[$2]++} END {for (d in sum) printf \"%s: %.2f\\n\", d, sum[d]/cnt[d]}'' data.csv"}, {"id": "shell-mp-4", "section": "Section B", "marks": 5, "question": "Describe `set -euo pipefail` and how `trap cleanup EXIT` guarantees temporary file removal on errors.", "rubric": ["Explain -e, -u, -o pipefail individually (3m)", "Explain trap EXIT firing on normal return or error abort (2m)"], "model_answer": "`-e` aborts on failed commands, `-u` errors on unset vars, `-o pipefail` propagates pipeline failures. Registering `trap ''rm -f \"$tmp\"'' EXIT` ensures cleanup runs regardless of how the script exits."}, {"id": "shell-mp-5", "section": "Section C", "marks": 10, "question": "Write a production-safe Bash log-rotation & error-summary script that accepts a directory path, handles filenames with spaces, rotates `.log` files > 10 MB, and outputs the top 5 HTTP 5xx error paths.", "rubric": ["Strict mode + arg validation + quoted paths (3m)", "Safe NUL-delimited `find` loop / size check (3m)", "Pipeline (`grep`/`awk`/`sort`/`uniq -c`/`head -n 5`) (4m)"], "model_answer": "Uses `#!/usr/bin/env bash`, `set -euo pipefail`, validates `$1` directory, iterates `while IFS= read -r -d '''' f` from `find \"$dir\" -type f -name ''*.log'' -size +10M -print0`, extracts 5xx endpoints via `awk ''$9 ~ /^5/ {print $7}'' | sort | uniq -c | sort -nr | head -n 5`, and archives safely."}]');
INSERT OR IGNORE INTO subjects (id, course_id, quadrant_key, title, short_title, topic, unit, instructor, badge_color, summary, subtitles_transcript, slide_crops, source_citations, mermaid_diagram) VALUES ('subj-dbms', 'course-sample-cs-core', 'bottom_left', 'DBMS', 'DBMS', 'Normalization (BCNF), B+ Trees & ARIES Recovery', 'Unit III & IV', 'Prof. S. Nair', '#8B5CF6', 'Covers functional dependency closure, 3NF/BCNF decomposition properties, B+ tree disk-paged indexing, ACID isolation & Two-Phase Locking, and ARIES Write-Ahead Logging recovery.', '[{"timestamp": "00:31:15", "text": "Lossless join holds when R1 intersect R2 is a superkey of either R1 or R2."}, {"timestamp": "00:36:40", "text": "B+ trees keep all data pointers in doubly linked leaf pages for fast range scans."}, {"timestamp": "00:42:10", "text": "ARIES repeats history during Redo, then undoes uncommitted losers using CLRs."}]', '[{"url": "data:image/svg+xml;base64,", "caption": "ARIES Analysis / Redo / Undo", "citation": "From: CMU YouTube 18:40", "source_id": "src-sample-youtube", "timestamp": "00:42:10"}, {"url": "data:image/svg+xml;base64,", "caption": "3NF vs BCNF Functional Dependencies", "citation": "From: DBMS_Normalization_Lab_Matrix.xlsx", "source_id": "src-sample-xlsx", "timestamp": "00:31:15"}]', '[{"source_id": "src-sample-xlsx", "title": "DBMS_Normalization_Lab_Matrix.xlsx", "location": "Sheets 1-2"}, {"source_id": "src-sample-youtube", "title": "CMU ARIES Recovery Lecture", "location": "04:12-18:40"}]', 'flowchart TD
    A["1NF Atomic Attributes"] --> B["2NF No Partial Dependency"]
    B --> C["3NF No Transitive Dependency"]
    C --> D["BCNF Every Determinant is Candidate Key"]
    D --> E["ARIES WAL: Analysis -> Redo -> Undo"]');
INSERT OR IGNORE INTO subject_details (subject_id, key_concepts, math_formulas) VALUES ('subj-dbms', '[{"title": "BCNF vs 3NF Trade-off", "explanation": "BCNF eliminates all FD-driven redundancy (every determinant X in X -> Y is a superkey), always achieves lossless join, but may sacrifice dependency preservation that 3NF guarantees.", "citation": "DBMS_Normalization_Lab_Matrix.xlsx"}, {"title": "B+ Tree Indexing & Leaf Linkage", "explanation": "Internal nodes hold only separator keys maximizing fanout; all record pointers live in linked leaf nodes so range queries `BETWEEN` scan leaves sequentially.", "citation": "4_Subject_Split_Lecture.mp4 36:40"}, {"title": "ARIES Steal / No-Force & 3-Phase Recovery", "explanation": "Allows dirty pages to flush early (Steal) without forcing all pages at commit (No-Force). Recovery runs Analysis, Redo (repeats history), and Undo (writes idempotent CLRs).", "citation": "CMU YouTube 18:40"}, {"title": "Conflict Serializability & Strict 2PL", "explanation": "A schedule is conflict-serializable iff its precedence graph is acyclic. Strict Two-Phase Locking holds exclusive locks until commit/abort to avoid cascading rollbacks.", "citation": "4_Subject_Split_Lecture.mp4 39:00"}]', '[{"name": "B+ Tree Maximum Height", "latex": "h \\le \\left\\lceil \\log_{\\lceil m/2 \\rceil}\\!\\left(\\frac{N}{2}\\right) \\right\\rceil + 1", "note": "High order m (e.g. 200) keeps height <= 4 even for millions of rows"}, {"name": "Lossless Binary Decomposition Check", "latex": "(R_1 \\cap R_2)^+ \\supseteq R_1 \\quad \\lor \\quad (R_1 \\cap R_2)^+ \\supseteq R_2", "note": "Common attributes must be a superkey of at least one fragment"}, {"name": "Block Nested-Loop Join Cost", "latex": "\\text{Cost} = B_R + \\left\\lceil \\frac{B_R}{M - 2} \\right\\rceil \\cdot B_S", "note": "M = available buffer pool pages"}]');
INSERT OR IGNORE INTO study_plans (subject_id, target_days, daily_hours, schedule_json) VALUES ('subj-dbms', 14, 3.0, '[{"day": 1, "id": "dbms-day-1", "title": "Day 1: ER Modeling & Relational Algebra", "phase": "Foundations", "priority": "High", "focus": "ER Modeling & Relational Algebra", "description": "Review visual notes & formulas, solve 5 recall problems, and complete 1 timed rubric drill on ER Modeling & Relational Algebra.", "hours": 3.0, "estimated_hours": 3.0, "tasks": [{"id": "dbms-d1-t1", "text": "Review visual notes & formulas for ER Modeling & Relational Algebra", "duration_min": 60}, {"id": "dbms-d1-t2", "text": "Solve 5 active-recall problems on ER Modeling & Relational Algebra", "duration_min": 60}, {"id": "dbms-d1-t3", "text": "Write 1 timed exam rubric answer (Foundations)", "duration_min": 60}]}, {"day": 2, "id": "dbms-day-2", "title": "Day 2: Functional Dependencies & Attribute Closure", "phase": "Foundations", "priority": "High", "focus": "Functional Dependencies & Attribute Closure", "description": "Review visual notes & formulas, solve 5 recall problems, and complete 1 timed rubric drill on Functional Dependencies & Attribute Closure.", "hours": 3.0, "estimated_hours": 3.0, "tasks": [{"id": "dbms-d2-t1", "text": "Review visual notes & formulas for Functional Dependencies & Attribute Closure", "duration_min": 60}, {"id": "dbms-d2-t2", "text": "Solve 5 active-recall problems on Functional Dependencies & Attribute Closure", "duration_min": 60}, {"id": "dbms-d2-t3", "text": "Write 1 timed exam rubric answer (Foundations)", "duration_min": 60}]}, {"day": 3, "id": "dbms-day-3", "title": "Day 3: 3NF, BCNF & Lossless Decomposition", "phase": "Foundations", "priority": "High", "focus": "3NF, BCNF & Lossless Decomposition", "description": "Review visual notes & formulas, solve 5 recall problems, and complete 1 timed rubric drill on 3NF, BCNF & Lossless Decomposition.", "hours": 3.0, "estimated_hours": 3.0, "tasks": [{"id": "dbms-d3-t1", "text": "Revie