INSERT OR IGNORE INTO quizzes (subject_id, questions_json) VALUES ('subj-dbms', '[{"id": "dbms-q1", "question": "In ARIES crash recovery, what is the primary purpose of Compensation Log Records (CLRs)?", "options": ["Record undo actions so a crash during recovery never repeats already-undone work", "Compress old checkpoints to save disk space", "Track read locks held by committed transactions", "Bypass Write-Ahead Logging during bulk inserts"], "correct_index": 0, "explanation": "CLRs carry an UndoNextLSN pointer allowing recovery to skip over already-undone updates if a crash occurs mid-recovery.", "citation": "CMU YouTube 18:40"}, {"id": "dbms-q2", "question": "A decomposition of R into (R1, R2) is guaranteed to be lossless-join if:", "options": ["R1 intersect R2 is a superkey of R1 or of R2", "R1 and R2 share no attributes at all", "R1 union R2 equals R and both are in 2NF", "Every attribute in R is prime"], "correct_index": 0, "explanation": "By Heath''s theorem, the intersection must functionally determine all attributes of at least one decomposed relation.", "citation": "DBMS_Normalization_Lab_Matrix.xlsx"}, {"id": "dbms-q3", "question": "Why are B+ trees preferred over standard B-trees for relational database indexes?", "options": ["Higher internal fanout (smaller height) and linked leaves for fast range scans", "B+ trees never require node splitting on insertion", "B+ trees store data in internal nodes to skip leaf lookups", "B+ trees support only equality predicates"], "correct_index": 0, "explanation": "Omitting data pointers from internal nodes increases branching factor, and sibling leaf pointers allow sequential range traversal.", "citation": "4_Subject_Split_Lecture.mp4 36:40"}, {"id": "dbms-q4", "question": "Strict Two-Phase Locking (Strict 2PL) prevents cascading aborts by:", "options": ["Holding all exclusive (X) locks until the transaction commits or aborts", "Releasing shared locks before acquiring exclusive locks", "Sorting transaction IDs alphabetically", "Running every query at READ UNCOMMITTED"], "correct_index": 0, "explanation": "No other transaction can read dirty uncommitted writes while X-locks are held until EOT.", "citation": "4_Subject_Split_Lecture.mp4 39:00"}, {"id": "dbms-q5", "question": "Which normal form allows a non-trivial FD X -> A when X is NOT a superkey, provided A is a prime attribute?", "options": ["3NF", "BCNF", "4NF", "1NF"], "correct_index": 0, "explanation": "3NF permits A to be prime; BCNF strictly requires X to be a superkey.", "citation": "DBMS_Normalization_Lab_Matrix.xlsx"}]');
INSERT OR IGNORE INTO model_papers (subject_id, title, time_allowed, max_marks, questions_json) VALUES ('subj-dbms', 'University Model Exam Paper — DBMS', '60 Minutes', 25, '[{"id": "dbms-mp-1", "section": "Section A", "marks": 2, "question": "State the two Write-Ahead Logging (WAL) rules that guarantee durability and atomicity.", "rubric": ["Flush log record before dirty page reaches disk (Steal/Undo) (1m)", "Flush commit log record before reporting commit (No-Force/Redo) (1m)"], "model_answer": "(1) Undo rule: flush a log record before its modified page is written to disk. (2) Redo rule: flush all log records up to commit before transaction commit completes."}, {"id": "dbms-mp-2", "section": "Section A", "marks": 3, "question": "Given R(A,B,C) with FDs {AB -> C, C -> B}, identify all candidate keys and check if R is in 3NF and BCNF.", "rubric": ["Candidate keys AB and AC (1m)", "3NF holds because B is prime (1m)", "BCNF violated by C -> B since C is not superkey (1m)"], "model_answer": "Candidate keys are AB and AC. R is in 3NF (B is prime in C -> B), but NOT in BCNF because C is not a superkey."}, {"id": "dbms-mp-3", "section": "Section B", "marks": 5, "question": "Explain the 3 phases of ARIES recovery (Analysis, Redo, Undo) and the role of Dirty Page Table RecLSN.", "rubric": ["Analysis scans from checkpoint to rebuild ATT & DPT (2m)", "Redo starts at smallest RecLSN in DPT and repeats history (2m)", "Undo rolls back active losers writing CLRs (1m)"], "model_answer": "Analysis finds active loser txns and dirty pages with earliest RecLSN. Redo replays all logged updates >= min(RecLSN) where pageLSN < logLSN. Undo walks backward through loser PrevLSNs emitting CLRs."}, {"id": "dbms-mp-4", "section": "Section B", "marks": 5, "question": "Compare 3NF vs BCNF decomposition using R(A,B,C) with {AB -> C, C -> B}: show a lossless BCNF split and identify the lost dependency.", "rubric": ["Decompose on C -> B into R1(C,B) and R2(C,A) (2m)", "Verify R1 intersect R2 = C is superkey of R1 (lossless) (2m)", "Note AB -> C is not preserved in a single relation (1m)"], "model_answer": "Splitting on C -> B gives R1(C,B) and R2(A,C). Since C -> B, C is a superkey of R1 so join is lossless, both are BCNF, but AB -> C spans both tables and is not preserved."}, {"id": "dbms-mp-5", "section": "Section C", "marks": 10, "question": "Analyze concurrency & storage performance: construct a precedence graph for S = R1(X); W2(X); W1(X); R2(Y); W1(Y) to test conflict serializability, explain Strict 2PL deadlock handling, and compute B+ tree height for N=10^7 rows with order m=200.", "rubric": ["Precedence graph edges T1->T2 and T2->T1 cycle -> not conflict serializable (4m)", "Strict 2PL wait-for graph / wound-wait or timeout deadlock prevention (3m)", "B+ tree height ceil(log_100(5e6)) + 1 = 5 levels (3m)"], "model_answer": "Schedule S has T1->T2 (R1(X) before W2(X)) and T2->T1 (W2(X) before W1(X), R2(Y) before W1(Y)), forming a cycle so S is not conflict-serializable. Strict 2PL resolves deadlocks via wait-for cycle detection or wait-die/wound-wait. With m=200 (min fanout 100), height <= ceil(log_100(5,000,000))+1 = 4+1 = 5 levels."}]');
INSERT OR IGNORE INTO subjects (id, course_id, quadrant_key, title, short_title, topic, unit, instructor, badge_color, summary, subtitles_transcript, slide_crops, source_citations, mermaid_diagram) VALUES ('subj-ml', 'course-sample-cs-core', 'bottom_right', 'Machine Learning', 'ML', 'Gradient Descent, SVMs & Bias-Variance Tradeoff', 'Unit II & IV', 'Prof. K. Rao', '#F59E0B', 'Covers empirical risk minimization, gradient descent & learning-rate dynamics, bias-variance decomposition, L1/L2 regularization, soft-margin Support Vector Machines, and evaluation metrics.', '[{"timestamp": "00:46:20", "text": "High bias underfits both train and validation; high variance shows a wide train-val gap."}, {"timestamp": "00:51:10", "text": "L1 Lasso drives small weights to exact zero; L2 Ridge shrinks weights smoothly."}, {"timestamp": "00:56:00", "text": "Support vectors satisfy alpha_i > 0 and lie on or inside the margin."}]', '[{"url": "data:image/svg+xml;base64,", "caption": "Bias-Variance U-Shaped Error Curve", "citation": "From: Stanford CS229 Notes", "source_id": "src-sample-web", "timestamp": "00:46:20"}, {"url": "data:image/svg+xml;base64,", "caption": "SVM Margin Maximization & Penalty C", "citation": "From: 4_Subject_Split_Lecture.mp4 56:00", "source_id": "src-sample-video", "timestamp": "00:56:00"}]', '[{"source_id": "src-sample-web", "title": "Stanford CS229 Bias-Variance & SVM Notes", "location": "Sections 1-2"}, {"source_id": "src-sample-video", "title": "4_Subject_Split_Lecture.mp4", "location": "45:00-60:00"}]', 'flowchart LR
    A["Raw Features X"] --> B["Train/Val Split + Scaling"]
    B --> C["Gradient Descent / SVM Margin"]
    C --> D["Cross-Validation ROC-AUC & F1"]
    D --> E["Bias-Variance Tuning"]');
INSERT OR IGNORE INTO subject_details (subject_id, key_concepts, math_formulas) VALUES ('subj-ml', '[{"title": "Bias-Variance Decomposition", "explanation": "MSE splits into squared bias (error from overly simple model assumptions), variance (sensitivity to training sample fluctuations), and irreducible Bayes noise.", "citation": "Stanford CS229 Notes"}, {"title": "L1 (Lasso) vs L2 (Ridge) Regularization", "explanation": "L1 adds lambda||w||_1 yielding sparse feature selection (diamond constraint corners); L2 adds lambda||w||_2^2 yielding smooth shrinkage and better conditioning.", "citation": "4_Subject_Split_Lecture.mp4 51:10"}, {"title": "Soft-Margin SVM & Kernel Trick", "explanation": "Maximizes margin 2/||w|| while trading slack violations via hyperparameter C. Inner products <x_i, x_j> generalize via positive-semidefinite kernels like RBF.", "citation": "Stanford CS229 Notes"}, {"title": "Precision, Recall & Imbalanced Metrics", "explanation": "Accuracy misleads on skewed classes; F1 harmonic mean balances Precision TP/(TP+FP) and Recall TP/(TP+FN), while PR-AUC tracks minority class performance.", "citation": "4_Subject_Split_Lecture.mp4 58:00"}]', '[{"name": "MSE Bias-Variance Decomposition", "latex": "\\mathbb{E}\\big[(y - \\hat{f}(x))^2\\big] = \\text{Bias}[\\hat{f}(x)]^2 + \\text{Var}[\\hat{f}(x)] + \\sigma^2", "note": "Regularization reduces Var at the cost of small Bias increase"}, {"name": "Gradient Descent Update Step", "latex": "\\theta_{t+1} = \\theta_t - \\eta \\nabla_\\theta J(\\theta_t)", "note": "Feature standardization prevents ill-conditioned oscillation"}, {"name": "RBF Gaussian Kernel", "latex": "K(x, z) = \\exp\\!\\left(-\\gamma \\|x - z\\|_2^2\\right)", "note": "Implicitly maps inputs into infinite-dimensional feature space"}]');
