INSERT OR IGNORE INTO quizzes (subject_id, questions_json) VALUES ('subj-ml', '[{"id": "ml-q1", "question": "A model achieves 99% training accuracy but only 64% validation accuracy. Which diagnosis and fix is most appropriate?", "options": ["High variance (overfitting) — increase regularization or collect more data", "High bias (underfitting) — decrease regularization and add polynomial features", "Zero irreducible noise — remove validation set", "Feature scaling error — increase learning rate 100x"], "correct_index": 0, "explanation": "A large gap between training and validation accuracy indicates overfitting (high variance).", "citation": "Stanford CS229 Notes"}, {"id": "ml-q2", "question": "Why does L1 (Lasso) regularization produce exact zero weights more often than L2 (Ridge)?", "options": ["Its L1 ball constraint has sharp diamond corners aligned with coordinate axes", "L1 uses a second-order Hessian matrix", "L2 cannot be differentiated at w=0", "L1 squares all weights before summing"], "correct_index": 0, "explanation": "Loss contours typically intersect the L1 diamond vertices on coordinate axes, setting non-essential weights to zero.", "citation": "4_Subject_Split_Lecture.mp4 51:10"}, {"id": "ml-q3", "question": "In a Soft-Margin SVM, increasing hyperparameter C to a very large value causes:", "options": ["Narrower margin with fewer training violations (lower bias, higher variance)", "Wider margin ignoring training outliers", "Automatic conversion from RBF to linear kernel", "Zero support vectors"], "correct_index": 0, "explanation": "Large C heavily penalizes slack xi_i, forcing tight separation of training points.", "citation": "Stanford CS229 Notes"}, {"id": "ml-q4", "question": "On a fraud dataset where 99.5% of transactions are legitimate, which metric is most informative?", "options": ["Precision-Recall AUC and F1-score", "Raw classification accuracy", "Mean Squared Error on class labels", "Training epoch count"], "correct_index": 0, "explanation": "Predicting all-legitimate gives 99.5% accuracy while catching 0% of fraud; PR-AUC and F1 measure minority class quality.", "citation": "4_Subject_Split_Lecture.mp4 58:00"}, {"id": "ml-q5", "question": "Why must feature scaling (mean=0, std=1) be fit ONLY on the training fold and applied to validation/test folds?", "options": ["Fitting on test/validation leaks distribution statistics into training evaluation", "Test sets do not contain numeric columns", "Standardization changes the number of features", "Validation accuracy must always stay lower than training accuracy"], "correct_index": 0, "explanation": "Using validation mean/std during preprocessing introduces data leakage and optimistic bias.", "citation": "Stanford CS229 Notes"}]');
INSERT OR IGNORE INTO model_papers (subject_id, title, time_allowed, max_marks, questions_json) VALUES ('subj-ml', 'University Model Exam Paper — Machine Learning', '60 Minutes', 25, '[{"id": "ml-mp-1", "section": "Section A", "marks": 2, "question": "Write the bias-variance decomposition equation for Mean Squared Error and define each term.", "rubric": ["Equation Bias^2 + Var + sigma^2 (1m)", "Clear definitions of Bias, Variance, irreducible noise (1m)"], "model_answer": "E[(y - f_hat(x))^2] = Bias[f_hat(x)]^2 + Var[f_hat(x)] + sigma^2, capturing systematic approximation error, sample sensitivity, and intrinsic label noise."}, {"id": "ml-mp-2", "section": "Section A", "marks": 3, "question": "Compute Precision, Recall, and F1-score when TP=40, FP=10, FN=10, TN=940.", "rubric": ["Precision = 40/50 = 0.80 (1m)", "Recall = 40/50 = 0.80 (1m)", "F1 = 2PR/(P+R) = 0.80 (1m)"], "model_answer": "Precision = 40/(40+10) = 0.80; Recall = 40/(40+10) = 0.80; F1 = 2*(0.8*0.8)/(0.8+0.8) = 0.80."}, {"id": "ml-mp-3", "section": "Section B", "marks": 5, "question": "Explain geometrically why L1 Lasso promotes sparsity whereas L2 Ridge shrinks coefficients toward zero without eliminating them.", "rubric": ["Compare L1 diamond vs L2 circle constraint geometry (3m)", "Explain axis intersection & subgradient behavior (2m)"], "model_answer": "Elliptical MSE contours strike the sharp corners of the L1 diamond lying directly on coordinate axes (w_j = 0), whereas the smooth L2 hypersphere typically intersects off-axis."}, {"id": "ml-mp-4", "section": "Section B", "marks": 5, "question": "Explain the Kernel Trick in Support Vector Machines and how RBF parameters gamma and C affect decision boundaries.", "rubric": ["Dot-product replacement K(x,z) = phi(x)^T phi(z) without explicit high-dim transform (2m)", "High gamma -> narrow localized Gaussian peaks (overfit risk) (1.5m)", "High C -> strict margin penalty (1.5m)"], "model_answer": "Dual SVM depends only on inner products <x_i, x_j>, replaced by K(x_i, x_j) in O(d). Large gamma shrinks kernel radius causing wiggly boundaries; large C penalizes margin slack heavily."}, {"id": "ml-mp-5", "section": "Section C", "marks": 10, "question": "Design a leak-free ML pipeline for an imbalanced credit-default dataset (2% positive rate): justify train/val/test splitting, preprocessing inside cross-validation, metric selection, and diagnosing learning curves.", "rubric": ["Stratified split + scaler fit strictly inside CV folds (3m)", "Class weighting / threshold tuning + PR-AUC/F1 over accuracy (3m)", "Diagnosing high bias vs high variance learning curves & mitigation actions (4m)"], "model_answer": "Use stratified split + k-fold CV where imputers/scalers fit strictly inside each train fold to prevent leakage. Optimize class-weighted logistic/GBDT models tracking PR-AUC and F1. Converging high error curves mean high bias (add features/reduce lambda); wide train-val gap means high variance (increase regularization/add data)."}]');

